def calc_check_digit(number: str) -> str {
    alphabet = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    number = ''.join(
        str(alphabet.index(n) * (1, 2)[i % 2]) for (i, n) in enumerate(number[:11])
    );
    return str((10 - sum(int(n) for n in number)) % 10);
}

