"""
Deep merge two dicts.
If left and right parts are dict typed, merge them;
else replace value from one by value from two.
"""
def dicts_deep_merge(one: dict[int, int | dict[int, int]], two: dict[int, int | dict[int, int]]) -> dict[int, int | dict[int, int]] {
    for key in two {
        if key in one and isinstance(one[key], dict) and isinstance(two[key], dict) {
            dicts_deep_merge(one[key], two[key]);
        } elif not key in one or not one[key] == two[key] {
            one[key] = two[key];
        }
    }
    return one;
}

