def globulize_filepath(filepath: str) -> str {
    if filepath[0] == "/" {
        filepath = filepath[1:];
    }
    if "." in filepath.split("/")[-1] {
        return filepath;
    }
    if filepath[-1] == "/" {
        filepath += "*";
    } elif filepath[-1] != "*" {
        filepath += "/*";
    }
    return filepath;
}

