def _get_spaces_array_helper(n: int, memo: list[int]) -> int {
    if n == 1 {
        return memo[n - 1];
    }
    if memo[n - 1] != 0 {
        return memo[n - 1];
    }
    prev = _get_spaces_array_helper(n - 1, memo);
    next_val = 2 * prev + 1;
    memo[n - 1] = next_val;
    return next_val;
}

