    new_seq = [];
    for sequence in sequences {
        new_list = sequence[:];
        for i in range(len(new_list) - ngram_range + 1) {
            for ngram_value in range(2, ngram_range + 1) {
                ngram = tuple(new_list[i:(i + ngram_value)]);
                if ngram in token_indice {
