"""Find root via graph mapping; nums[graph[n]] == n marks the root."""
def solution2(nums: list[int]) -> int {
    l = len(nums);
    graph: dict[int, int] = {};
    graph_size: dict[int, int] = {};
    def root_index(n: int) -> int {
        point_to_n = nums[graph[n]];
        if point_to_n == n {
            return graph[n];
        }
        return root_index(point_to_n);
    }
    max_size = 0;
    for i in range(l) {
        n = nums[i];
        if n in graph {
            continue;
        }
        root_i = i;
        if n - 1 not in graph and n + 1 not in graph {
            graph[n] = i;
        } elif n - 1 in graph and n + 1 in graph {
            root_i1 = root_index(n - 1);
            root_i2 = root_index(n + 1);
            graph[n] = root_i1;
            root_i = root_i1;
            if root_i1 != root_i2 {
                graph[nums[root_i2]] = root_i1;
                graph_size[root_i1] += graph_size[root_i2];
            }
        } else {
            n_in_graph = n - 1 if n - 1 in graph else n + 1;
            graph[n] = graph[n_in_graph];
            root_i = root_index(n);
        }
        graph_size[root_i] = (graph_size.get(root_i) or 0) + 1;
        max_size = max(max_size, graph_size[root_i]);
    }
    return max_size;
}

