def round_robin(teams: list[str | int] | tuple[str | int, ...], rounds: int | None = None) -> list[list[tuple[str | int, str | int]]] {
    if not isinstance(teams, list) {
        teams = [t for t in teams];
    }
    if len(teams) % 2 {
        teams.append(0);
    }
    count = len(teams);
    half = int(count / 2);
    if rounds is None {
        rounds = count - 1;
    }
    schedule = [];
    for turn in range(rounds) {
        pairings = [];
        for i in range(half) {
            pairings.append((teams[i], teams[count - i - 1]));
        }
        teams.insert(1, teams.pop());
        schedule.append(pairings);
    }
    return schedule;
}

