""" sets up markers for pivot point, left marker
and right marker then iteratively swap into place
as the markers converge"""
def partition(array: list[int], start: int, end: int) -> int {
    piv = array[start];
    left = start + 1;
    right = end;
    done = False;
    while not done {
        while left <= right and array[left] <= piv {
            left += 1;
        }
        while array[right] >= piv and right >= left {
            right -= 1;
        }
        if right < left {
            done = True;
        } else {
            temp = array[left];
            array[left] = array[right];
            array[right] = temp;
        }
    }
    temp = array[start];
    array[start] = array[right];
    array[right] = temp;
    return right;
}

