        'yeah',
        'um',
        'ah',
        'a',
        'the',
        'o.k.',
        'your',
        'hm',
        'oh' 'okay',
        'my',
        'that',
        'i',
        'alright',
        'bye',
        'uh',
        'i i',
        'oh'
    ];
