"""Removes list of base class."""
def removeBases(str: str) -> str {
    pos1 = -2;
    while pos1 < len(str) {
        pos1 = str.find(':', pos1 + 2);
        if pos1 < 0 {
            return str;
        }
        if pos1 == len(str) - 1 or str[pos1 + 1] != ':' {
            return str[:pos1];
        }
    }
    return str.strip();
}

