            xsize = patch_w + 2 * adj_overlay_x;
            ysize = patch_h + 2 * adj_overlay_y;
            patch_boundary.append((xoff, yoff, xsize, ysize));
        }
        f_obj.write('\n');
    }
    f_obj.close();
    return patch_boundary;
}

