def where_to_go(point1: int, point2: int, separator: str) -> str {
    if point1 < point2 {
        return str(point1) + separator + where_to_go(point1 + 1, point2, separator);
    } elif point2 < point1 {
        return str(point1) + separator + where_to_go(point1 - 1, point2, separator);
    }
    return str(point1);
}

