"""
Compare whether all unique whitespace-separated names in name2 appear in name1.

Returns 1 if contained, else 0.
"""
def contained_name(name1: str, name2: str) -> int {
    common_elements = 0;
    words1 = set(name1.split());
    for word in set(name2.split()) {
        if word in words1 {
            common_elements += 1;
        }
    }
    min_elements = min(
        len([s[0] for s in name1.split()]), len([t[0] for t in name2.split()])
    );
    if min_elements > 1 and min_elements == common_elements {
        return 1;
    }
    return 0;
}

