  """
def join(*parts: str) -> str {
    try {
        path = [parts[0].rstrip("/")];
    } except IndexError {
        raise TypeError("need at least one argument");
    }
    for p in parts[1:] {
        p = p.strip("/");
        if p.startswith(('hdfs:', 'file:')) {
            path = [p];
        } else {
            path.append(p);
        }
    }
    return "/".join(path);
}

