                _list[k] = left_half[i];
                i += 1;
            } else {
                _list[k] = right_half[j];
                j += 1;
            }
            k += 1;
        }
        while i < len(left_half) {
            _list[k] = left_half[i];
            i += 1;
            k += 1;
        }
        while j < len(right_half) {
